]:[['Understand the goal','We review the problem, your users and the tools you already use.'],['Define the solution','We agree on scope, deliverables and milestones before development.'],['Build and validate','We implement the solution and review progress with you.'],['Launch and support','We test, deploy and define the next steps for your product.']]);

let motionCleanup;
onMounted(()=>{
 const controller=new AbortController(),signal=controller.signal,reduce=matchMedia('(prefers-reduced-motion: reduce)');
 const targets=[...document.querySelectorAll('.section-heading,.service-card,.software-panel,.process-grid article,.about-copy,.contact-panel')];
 const observer=new IntersectionObserver(entries=>entries.forEach(e=>{if(e.isIntersecting){e.target.classList.add('revealed');observer.unobserve(e.target)}}),{threshold:.12});
 targets.forEach((el,i)=>{el.style.setProperty('--reveal-delay',(i%4)*65+'ms');el.classList.add('motion-reveal');observer.observe(el)});
 document.querySelectorAll('[data-depth]').forEach(el=>{el.addEventListener('pointermove',e=>{if(reduce.matches||e.pointerType==='touch')return;const r=el.getBoundingClientRect();el.style.setProperty('--rx',((.5-(e.clientY-r.top)/r.height)*7)+'deg');el.style.setProperty('--ry',(((e.clientX-r.left)/r.width-.5)*9)+'deg')},{signal});el.addEventListener('pointerleave',()=>{el.style.setProperty('--rx','0deg');el.style.setProperty('--ry','0deg')},{signal})});
 motionCleanup=()=>{controller.abort();observer.disconnect()};
});
